package net.civeira.phylax.feature.observe.viewer;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.QueryParam;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.feature.observe.access.ObserveAccess;
import net.civeira.phylax.feature.observe.access.ObserveGrant;
import net.civeira.phylax.feature.observe.access.ObserveLevel;

/**
 * Api of the viewer, behind the same security as the rest of the application: the bearer token is
 * validated by the application and {@link ObserveAccess} checks the roles of the level of each
 * operation (401 anonymous, 403 without the roles, by the NotAllowedException mapper).
 */
@Path("observe/api")
@Produces(MediaType.APPLICATION_JSON)
@RequestScoped
@RequiredArgsConstructor
public class ObserveApiController {

  private final ObserveAccess access;
  private final ObserveQueries queries;
  private final CurrentRequest current;

  @GET
  @Path("me")
  public Response me() {
    return with(ObserveLevel.READ,
        grant -> Map.of("user", grant.user(), "levels", grant.effective()));
  }

  @GET
  @Path("sources")
  public Response sources() {
    return with(ObserveLevel.READ, grant -> queries.sources(grant.has(ObserveLevel.ADMIN)));
  }

  @GET
  @Path("logs")
  public Response logs(@QueryParam("src") final List<String> src,
      @QueryParam("level") final String level, @QueryParam("q") final String text,
      @QueryParam("traceId") final String traceId, @QueryParam("from") final Long from,
      @QueryParam("to") final Long to, @QueryParam("limit") final Integer limit) {
    return with(ObserveLevel.READ,
        grant -> queries.logs(sources(src), level, text, traceId, from, to, limit));
  }

  @GET
  @Path("traces")
  public Response traces(@QueryParam("src") final List<String> src,
      @QueryParam("q") final String text, @QueryParam("errors") final boolean errors,
      @QueryParam("from") final Long from, @QueryParam("to") final Long to,
      @QueryParam("limit") final Integer limit) {
    return with(ObserveLevel.READ,
        grant -> queries.traces(sources(src), text, errors, from, to, limit));
  }

  @GET
  @Path("traces/{traceId}")
  public Response trace(@PathParam("traceId") final String traceId,
      @QueryParam("from") final Long from, @QueryParam("to") final Long to) {
    return with(ObserveLevel.READ, grant -> queries.trace(traceId, from, to));
  }

  private static Set<String> sources(final List<String> src) {
    return null == src ? Set.of() : Set.copyOf(src);
  }

  private Response with(final ObserveLevel level, final Function<ObserveGrant, Object> action) {
    ObserveGrant grant = access.require(current.getActor(), level);
    return Response.ok(action.apply(grant)).header("Cache-Control", "no-store").build();
  }
}
